-- movie_database.sql
-- Create database
CREATE DATABASE IF NOT EXISTS cinestar;

USE cinestar;

-- Movies Table
CREATE TABLE movies (
    movie_id INT PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    synopsis TEXT,
    starring VARCHAR(255),
    director VARCHAR(255),
    genre VARCHAR(50),
    language VARCHAR(50),
    runtime VARCHAR(15),
    release_date DATE,
    image_path VARCHAR(255),
    status ENUM('Now_showing', 'Coming_soon'),
    age_rating ENUM(
        'PG',
        'PG13',
        'NC16',
        'M18',
        'R21',
        'Rating to be advised'
    ) NOT NULL
);

-- Cinemas Table
CREATE TABLE cinemas (
    cinema_id INT PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    address VARCHAR(255) NOT NULL
);

-- Halls Table
CREATE TABLE halls (
    hall_id INT,
    cinema_id INT,
    hall_number INT NOT NULL,
    PRIMARY KEY (hall_id, cinema_id),
    FOREIGN KEY (cinema_id) REFERENCES cinemas(cinema_id) ON DELETE CASCADE
);

CREATE TABLE hall_movies (
    hall_id INT,
    cinema_id INT,
    movie_id INT,
    PRIMARY KEY (hall_id, cinema_id, movie_id),
    FOREIGN KEY (hall_id, cinema_id) REFERENCES halls(hall_id, cinema_id) ON DELETE CASCADE,
    FOREIGN KEY (movie_id) REFERENCES movies(movie_id) ON DELETE CASCADE
);

-- Seats Table
CREATE TABLE seats (
    seat_id INT,
    hall_id INT,
    cinema_id INT,
    seat_row VARCHAR(3) NOT NULL,
    status ENUM('available', 'selected', 'unavailable') NOT NULL,
    PRIMARY KEY (cinema_id, hall_id, seat_id),
    FOREIGN KEY (hall_id, cinema_id) REFERENCES halls(hall_id, cinema_id) ON DELETE CASCADE
);

-- Showtimes Table
CREATE TABLE showtimes (
    showtime_id INT AUTO_INCREMENT PRIMARY KEY,
    movie_id INT,
    cinema_id INT,
    hall_id INT,
    date DATE NOT NULL,
    time TIME NOT NULL,
    standard_price DECIMAL(10, 2) NOT NULL,
    student_price DECIMAL(10, 2) NOT NULL,
    FOREIGN KEY (movie_id) REFERENCES movies(movie_id) ON DELETE CASCADE,
    FOREIGN KEY (cinema_id) REFERENCES cinemas(cinema_id) ON DELETE CASCADE,
    FOREIGN KEY (hall_id, cinema_id) REFERENCES halls(hall_id, cinema_id) ON DELETE CASCADE
);

-- Bookings Table
CREATE TABLE bookings (
    booking_id INT AUTO_INCREMENT PRIMARY KEY,
    -- Auto-incrementing booking ID
    movie_id INT,
    -- Foreign key linking to the movies table
    cinema_id INT,
    -- Foreign key linking to the cinemas table
    hall_id INT,
    -- Foreign key linking to the halls table
    showtime_id INT,
    -- Foreign key linking to the showtimes table
    reference_id VARCHAR(10) NOT NULL UNIQUE,
    -- Unique user-friendly reference ID
    payment_method ENUM('PayNow', 'Mastercard') NOT NULL,
    -- Payment method
    card_number VARCHAR (20),
    user_name VARCHAR(255),
    -- Name of the user (if available)
    user_email VARCHAR(255),
    -- Email of the user (if available)
    total_price DECIMAL(10, 2),
    -- Total price for the booking
    booking_date DATE DEFAULT CURRENT_DATE,
    -- Date when the booking was made
    FOREIGN KEY (movie_id) REFERENCES movies(movie_id) ON DELETE CASCADE,
    FOREIGN KEY (cinema_id) REFERENCES cinemas(cinema_id) ON DELETE CASCADE,
    FOREIGN KEY (hall_id, cinema_id) REFERENCES halls(hall_id, cinema_id) ON DELETE CASCADE,
    FOREIGN KEY (showtime_id) REFERENCES showtimes(showtime_id) ON DELETE CASCADE
);

-- BookingSeats Table
CREATE TABLE booking_seats (
    reference_id VARCHAR(10),
    -- Foreign key linking to reference_id in the bookings table
    seat_id INT,
    -- Foreign key linking to the seats table
    hall_id INT,
    -- Hall where the seat is located
    cinema_id INT,
    -- Cinema where the hall is located
    PRIMARY KEY (reference_id, cinema_id, hall_id, seat_id),
    -- Composite primary key
    FOREIGN KEY (reference_id) REFERENCES bookings(reference_id) ON DELETE CASCADE,
    FOREIGN KEY (cinema_id, hall_id, seat_id) REFERENCES seats(cinema_id, hall_id, seat_id) ON DELETE CASCADE
);

